dispKeyDetails() {
  if (!Enigmail.msg.securityInfo) {
    return;
  }

  const key = EnigmailKeyRing.getKeyById(Enigmail.msg.securityInfo.keyId);

  EnigmailWindows.openKeyDetails(window, key.keyId, false);
},

